--{{{ 一二级货币差异
---是否开启了一二级货币
function ServerDifferenceMgr:IsSecondaryCurrencyEnable()
    local flag = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 29)
    if flag then
        return checkNumber(flag.num) == 1
    end
    return false
end

---刷新活动页面导航栏
---@param itemId string[] @ 道具id列表
function ServerDifferenceMgr:RefreshNavigatorGoods(isShow)
    if isShow then
        local isPay = self:IsSecondaryCurrencyEnable()
        if isPay then
            CfUtils.RefreshTopGoods( {
                Constants.Currency.PayDiamondId,
                Constants.Currency.FreeDiamondId,
            })        
        else 
            CfUtils.RefreshTopGoods( {
                Constants.Currency.FreeDiamondId,
            })            
        end
    else 
        CfUtils.RefreshTopGoods( {
        })            
    end
    
end

---@class PriceInfo
---@field currency number 货币类型
---@field current number 真实价格
---@field productName string 商品名称  (可选参数)

---使用一、二级货币购买物品时,不足跳出虹晶快捷购买弹窗
---@param priceInfo PriceInfo
---@param callback fun(isSuccess:boolean)  货币充足,或虹晶购买成功则为true  (废弃了)
---@param callback2 fun(isSuccess:boolean)  需求变更(购买虹晶后不处理商品购买,需玩家再次确认).  由于之前使用此方法的大量地方在回调里处理了商品购买,不方便在各个地方修改,所以直接关闭了第一个回调.     如需回调,请使用第二个(第一个不会响应)
function ServerDifferenceMgr:WrapPrimaryCurrencyBuy(priceInfo, callback, callback2)
    if not self:IsSecondaryCurrencyEnable() then
        local currency  = checkInt(priceInfo.currency )
        if currency == Constants.Currency.PayDiamondId then
            printError("未开启一二级货币功能,理论上应该不存在需要一级货币购买的东西")
        end
        --没开启一二级货币功能,直接跳转猫眼石充值商店
        if currency == Constants.Currency.FreeDiamondId then
            local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(Constants.Currency.FreeDiamondId)
            GameUtils.SecondConfirm(
                    localize("_name_不足, 是否前往充值？", { _name_ = goodsVo.name }),
                    function()
                        OverseaStoreUtils.OpenStore(OverseaStoreConstants.StoreType.TopUp)
                    end
            )
        end
        
        ---其他情况也返回,容错
        local ownNum = GoodsUtils.GetThingNo(priceInfo.currency)
        if callback then
            callback(ownNum >= priceInfo.current)
        end
        return
    end

    local needPayDiamond = 0
    local needPayFreeDiamond = 0
    local isUseDiamond = false
    if priceInfo.currency == Constants.Currency.FreeDiamondId then
        local ownFreeNum = GoodsUtils.GetThingNo(priceInfo.currency)
        if ownFreeNum < priceInfo.current then
            needPayDiamond = priceInfo.current - ownFreeNum
            needPayFreeDiamond = ownFreeNum
        else
            needPayFreeDiamond = priceInfo.current
        end
        isUseDiamond = true
    elseif priceInfo.currency == Constants.Currency.PayDiamondId then
        needPayDiamond = priceInfo.current
        isUseDiamond = true
    end

    local ownPayDiamond = GoodsUtils.GetThingNo(Constants.Currency.PayDiamondId)
    if ownPayDiamond < needPayDiamond and isUseDiamond then
        ---@type CommonPrimaryCurrencyBuyPopup.InputData
        local data = {}
        data.needNum = needPayDiamond
        --data.payedCallback = callback
        data.payedCallback = callback2
        CfUtils.DialogOpen(Constants.UITypeIds.PrimaryCurrencyPopup, data)
    else
        if callback then
            local text
            local goodsConfMgr = GoodsConfMgr:GetInstance()
            local freeDiamondVo = goodsConfMgr:GetGoodsVoById(Constants.Currency.FreeDiamondId)
            local payDiamondVo = goodsConfMgr:GetGoodsVoById(Constants.Currency.PayDiamondId)
            if needPayFreeDiamond ~= 0 and needPayDiamond ~= 0 then
                if priceInfo.productName then
                    text = localize("确认花费_Num__Name_和_Num1__Name1_购买_ProductName_?",{_Num_ = needPayFreeDiamond, _Name_ = freeDiamondVo.name, _Num1_ = needPayDiamond, _Name1_ = payDiamondVo.name, _ProductName_ = priceInfo.productName})
                else
                    text = localize("确认花费_Num__Name_和_Num1__Name1_购买商品?",{_Num_ = needPayFreeDiamond, _Name_ = freeDiamondVo.name, _Num1_ = needPayDiamond, _Name1_ = payDiamondVo.name})
                end
            else
                local _Num_ = 0
                local _Name_ = ""
                if needPayFreeDiamond ~= 0 then
                    _Num_ = needPayFreeDiamond
                    _Name_ = freeDiamondVo.name
                else
                    _Num_ = needPayDiamond
                    _Name_ = payDiamondVo.name
                end
                if not isUseDiamond then
                    _Num_ = priceInfo.current
                    local goodsVo = goodsConfMgr:GetGoodsVoById(priceInfo.currency)
                    _Name_ = goodsVo.name
                end
                if priceInfo.productName then
                    text = localize("确认花费_Num__Name_购买_ProductName_?",{_Num_ = _Num_, _Name_ = _Name_, _ProductName_ = priceInfo.productName})
                else    
                    text = localize("确认花费_Num__Name_购买商品?",{_Num_ = _Num_, _Name_ = _Name_})
                end
            end
            GameUtils.SecondConfirm(
                    text,
                    function()
                        --需要消耗一级货币兑换二级货币的情况,新增兑换接口
                        if needPayFreeDiamond ~= 0 and needPayDiamond ~= 0  then
                            CfUtils.ConditionAppend("StoreDiamondChanges")
                            GameUtils.Request(Interfaces.StoreDiamondChanges, {num = needPayDiamond},
                                    function(request, response)
                                        CfUtils.ConditionRemove("StoreDiamondChanges")
                                        if checkInt(response.errCode) == 0 then
                                            local consume = {
                                                {
                                                    goodsId = Constants.Currency.PayDiamondId,
                                                    num     = -needPayDiamond
                                                }
                                            }
                                            GoodsUtils.DrawRewards(checkTable(consume))
                                            GoodsUtils.DrawRewards(response.data.rewards)
                                            callback(true)
                                        end
                                    end
                            )
                        else
                            callback(true)    
                        end
                    end,
                    nil,
                    nil,
                    nil,
                    nil,
                    nil,
                    nil,
                    nil,
                    nil,
                    CS.Engine.UI.UIModule.RootCanvas.transform
            )
        end
    end
end


